#!/bin/bash
# Build the ICLR 2027 submission: pdflatex + bibtex (texlive module on the cluster). Figures are regenerated by figures/make_*.py (flow-rl conda env).
set -e; cd "$(dirname "$0")"
module load texlive/20240312 2>/dev/null || true
pdflatex -interaction=nonstopmode -halt-on-error main1.tex >/dev/null
bibtex main1 >/dev/null
pdflatex -interaction=nonstopmode main1.tex >/dev/null
pdflatex -interaction=nonstopmode main1.tex >/dev/null
echo "built main1.pdf ($(grep -c 'Reference.*undefined\|Citation.*undefined' main1.log) undefined refs)"
